/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 */
function evaluateEvent({
    api,
    event
}) {
    let routeParam = api.context.props.route;
    let serviceGroupParam = api.context.props.serviceGroup;

    switch (routeParam) {
        case ("user-roles"):
            {
                return {
                    route: "user-roles",
                    params: {
                        "parentRoute": "success-dashboard"
                    },
                    fields: null
                };
            }
        case ("deflection-configuration-kb"):
            {
                let kb_def_id;

                if (serviceGroupParam == "0a7f1437533011101d87ddeeff7b12da") { //IT
                    kb_def_id = "b98b5b1507a13010c7d559bf1ad30021";
                } else if (serviceGroupParam == "b21e662bc3741110daf3eeb0d840dd24") { //HR
                    kb_def_id = "be61963cc3111110daf3eeb0d840dd27";
                }

                return {
                    route: "deflection-configuration",
                    params: {
                        heading: "Knowledge deflection",
                        description: "Includes only the relevant knowledge bases while determining the self-solved using Knowledge. Knowledge base articles related to service group are included as part of the base system configuration."
                    },
                    fields: {
                        sysId: kb_def_id
                    }
                };
            }
        case ("deflection-configuration-va"):
            {
                return {
                    route: "deflection-configuration",
                    params: {
                        heading: "Virtual Agent deflection",
                        description: "Configure the VA topics to determine the self-solved using VA conversations. Base system configuration depends on selected service group."
                    },
                    fields: {
                        sysId: "b7bb568153fe7110752addeeff7b12ad"
                    }
                };
            }
        case ("va-form"):
            {
                return {
                    route: "va-form",
                    params: {
                        id: "42902004eb913010226ed5c15252286e"
                    },
                    fields: {
                        name: "HR Default"
                    }
                };
            }
        case ("fulfilment-automation-level"):
            {
                return {
                    route: "fulfilment-automation-level",
                    params: null,
                    fields: null
                };
            }
        case ("pa-jobs-list"):
            {
                return {
                    route: "pa-jobs-list",
                    params: {
                        buValue: serviceGroupParam
                    },
                    fields: null
                };
            }
        case ("process-mining-projects"):
            {
                return {
                    route: "process-mining-projects",
                    params: {
                        serviceGroup: serviceGroupParam
                    },
                    fields: null
                };
            }
        case ("sys-property-config"):
            {
                return {
                    route: "sys-property-config",
                    params: null,
                    fields: null
                };
            }
        case ("kpi-details"):
            {
                return {
                    route: "kpi-details",
                    params: {
                        buValue: serviceGroupParam
                    },
                    fields: null
                };
            }
    }
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 * @param {any} params.imports
 */
function evaluateEvent({
    api,
    event
}) {
    var res = {};
    Object.keys(api.context.props).forEach(function(propName) {
        if (api.context.props[propName])
            res[propName] = api.context.props[propName];
    });
    return {
        propName: "pageParams",
        value: res
    };
}

